import React, { useState, useEffect } from 'react';

const MortgageCalculator = ({ show, onClose, defaultPrice = 0 }) => {
  const [price, setPrice] = useState(defaultPrice);
  const [quantity, setQuantity] = useState(1);
  const [shipping, setShipping] = useState(50); // Default shipping
  const [total, setTotal] = useState(0);

  useEffect(() => {
    if (show) {
      setPrice(defaultPrice || 0);
    }
  }, [show, defaultPrice]);

  useEffect(() => {
    setTotal((price * quantity) + shipping);
  }, [price, quantity, shipping]);

  if (!show) return null;

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.5)', zIndex: 1060 }}>
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content shadow">
          <div className="modal-header bg-light">
            <h5 className="modal-title">🧮 حاسبة التكلفة التقديرية</h5>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>
          <div className="modal-body">
            <div className="mb-3">
              <label className="form-label">سعر المذكرة/الكتاب (جنيه)</label>
              <input type="number" className="form-control" value={price} onChange={e => setPrice(Number(e.target.value))} />
            </div>
            <div className="mb-3">
              <label className="form-label">الكمية</label>
              <input type="number" className="form-control" value={quantity} min="1" onChange={e => setQuantity(Number(e.target.value))} />
            </div>
            <div className="mb-3">
              <label className="form-label">مصاريف الشحن (تقديري)</label>
              <select className="form-select" value={shipping} onChange={e => setShipping(Number(e.target.value))}>
                <option value="30">القاهرة والجيزة (30 ج)</option>
                <option value="50">الإسكندرية والدلتا (50 ج)</option>
                <option value="70">الصعيد (70 ج)</option>
                <option value="100">المحافظات الحدودية (100 ج)</option>
              </select>
            </div>
            
            <div className="alert alert-primary text-center mt-2 mb-0">
              <small className="d-block text-muted mb-1">الإجمالي الكلي</small>
              <h2 className="fw-bold m-0">{total.toLocaleString()} جنيه</h2>
            </div>
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onClose}>إغلاق</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MortgageCalculator;
